    color-scheme: light;
    --card: #fdfcf8;
    --ink: #2a2921;
    --ink-soft: #57543f;
    --muted: #8b8878;
    --faint: #b6b3a2;
    --line: #dbd8cb;
    --line-strong: #c7c3b2;
    --head: #f0eee3;
    --accent: #1e6f4c;
